      function text(t, x, y, o) { o = o || {}; g.save(); g.globalAlpha = o.al == null ? 1 : o.al; g.font = `${o.w || 500} ${o.s || fs}px ${o.mono ? MONO : FONT}`; g.fillStyle = o.c || SC.ink2; g.textAlign = o.a || 'left'; g.textBaseline = o.b || 'alphabetic'; g.fillText(t, x, y); g.restore(); }
