        head = ['', 'формула', `выборка ${NS}`];
        rows = [['среднее', f(r.mn), f(mean)], ['медиана', f(r.md), f(sq(s, 0.5))], ['ст. откл.', f(r.sd), f(sd)], ['95-й перцентиль', f(r.p95), f(sq(s, 0.95))]];
        last = { mean, med: sq(s, 0.5) };
