    log_normal: { title: 'Асимметрия сумм покупок до и после логарифмирования', badge: B, lang: 'python', ...RUN.log_normal },
    mean_median: { title: 'Как изменятся среднее и медиана без 1% самых дорогих чеков', badge: 'проверено: pandas 3.0.5', lang: 'python', ...RUN.mean_median },
    scipy_basics: { title: 'Общие методы распределений в scipy.stats', badge: B, lang: 'python', ...RUN.scipy_basics },
